@propertyWrapper
struct Dirty<Value> {
    private var slot: Value?
    private let build: () -> Value
    init(build: @escaping () -> Value) { self.build = build }

    var wrappedValue: Value {
        mutating get { slot ??= build() }
        set { slot = nil }                 // writing the property invalidates
    }
}
